#[test]
fn kind_defaults_to_note_is_filterable_and_reclassifies() {
    let dir = tmp();
    let d = dir.to_string_lossy().into_owned();
    cli::run(vec!["add".into(), "unclassified".into(), "--dir".into(), d.clone()], "bsc memory").expect("bare add");
    cli::run(
        vec!["add".into(), "a rule".into(), "--kind".into(), "lesson".into(), "--dir".into(), d.clone()],
        "bsc memory",
    )
    .expect("add lesson");

    let store = bsc_json_store::Store::new(dir, "memory");
    let items = store_memories(&store);
    // Omitting --kind must not MISLABEL. `note` is the absence of a classification, not a guess.
    assert_eq!(items.iter().find(|m| m.text == "unclassified").unwrap().kind, KIND_NOTE);
    let lesson = items.iter().find(|m| m.text == "a rule").unwrap().clone();
    assert_eq!(lesson.kind, KIND_LESSON);

    // The filter is what the reading surfaces key on, so it has to actually narrow.
    let only_lessons = filter_and_order(&items, &Filter { kind: Some("lesson"), ..Default::default() });
    assert_eq!(only_lessons.len(), 1, "kind filter narrows to that kind alone");
    assert_eq!(only_lessons[0].text, "a rule");
    // Case-insensitively, like every other facet — a kind typed with a capital is the same kind.
    assert_eq!(filter_and_order(&items, &Filter { kind: Some("LESSON"), ..Default::default() }).len(), 1);

    // The promotion path off `note` / off `ambient`.
    let unclassified = items.iter().find(|m| m.text == "unclassified").unwrap().id.clone();
    cli::run(
        vec!["kind".into(), unclassified.clone(), "highlight".into(), "--dir".into(), d.clone()],
        "bsc memory",
    )
    .expect("reclassify");
    let after = store_memories(&store);
    assert_eq!(after.iter().find(|m| m.text == "unclassified").unwrap().kind, KIND_HIGHLIGHT);
    // Reclassifying must not disturb the other facets.
    assert_eq!(after.iter().find(|m| m.text == "unclassified").unwrap().horizon, HORIZON_NOW);
    assert_eq!(after.iter().find(|m| m.text == "unclassified").unwrap().status, "open");

    // An unknown kind is REFUSED, on both doors — stored, it would be a memory under no tab at all.
    assert!(
        cli::run(vec!["add".into(), "x".into(), "--kind".into(), "lessons".into(), "--dir".into(), d.clone()], "bsc memory")
            .is_err(),
        "a near-miss kind on `add` is refused, not stored"
    );
    assert!(
        cli::run(vec!["kind".into(), unclassified, "urgent".into(), "--dir".into(), d.clone()], "bsc memory").is_err(),
        "a near-miss kind on `kind` is refused"
    );
    // …and the refusal left nothing behind.
    assert!(store_memories(&store).iter().all(|m| m.text != "x"), "a refused add writes no record");
}

#[test]
fn every_declared_kind_is_reachable_through_the_cli() {
    // The population guard. `KINDS` is what the CLI help, the `kind` verb and the workspace tabs all
    // read; a kind that is declared but rejected by `is_kind` would be advertised and unusable.
    let dir = tmp();
    let d = dir.to_string_lossy().into_owned();
    assert!(KINDS.len() >= 5, "the kind vocabulary shrank — update the surfaces that enumerate it");
    for k in KINDS {
        cli::run(
            vec!["add".into(), format!("a {k}"), "--kind".into(), (*k).into(), "--dir".into(), d.clone()],
            "bsc memory",
        )
        .unwrap_or_else(|e| panic!("declared kind '{k}' was refused by add: {e}"));
    }
    let items = store_memories(&bsc_json_store::Store::new(dir, "memory"));
    for k in KINDS {
        assert!(items.iter().any(|m| m.kind == *k), "no memory stored for declared kind '{k}'");
    }
}

#[test]
fn a_target_may_name_its_node_type_explicitly() {
    // A feature slug and a plan ref are the SAME SHAPE, so nothing can tell them apart without being
    // told. The prefix is how — and it needs no grammar change, because `parse_link_specs` splits
    // `rel:ref` on the FIRST colon only.
    let links = parse_link_specs("about:feature:auth,about:session:studio-code:director,about:bare-slug");
    assert_eq!(links[0], Link::new("feature:auth", "about"));
    assert_eq!(links[1], Link::new("session:studio-code:director", "about"));
    assert_eq!(links[2], Link::new("bare-slug", "about"));

    assert_eq!(target_type("feature:auth"), Some("feature"));
    assert_eq!(target_type("session:studio-code:director"), Some("session"));
    assert_eq!(target_type("Record:bsc-graph--methods.rs"), Some("record"), "the prefix is case-insensitive");
    // A colon that is not a known type is NOT a prefix — a bare id keeps its whole self as the target.
    assert_eq!(target_type("bsc-graph--methods.rs"), None);
    assert_eq!(target_type("wat:thing"), None);
    // …and the degenerate forms do not panic or half-match.
    assert_eq!(target_type("feature:"), None, "a prefix with no target is not a typed target");
    assert_eq!(target_type("feature"), None);
}
